using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Users.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Users.Queries.GetUsers;public sealed class GetUsersQueryHandler(IUserRepository repository):IRequestHandler<GetUsersQuery,Result<IReadOnlyList<UserDto>>>{public async Task<Result<IReadOnlyList<UserDto>>>Handle(GetUsersQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<UserDto>>((await repository.GetAllAsync(cancellationToken)).Select(UserDto.FromEntity).ToList());}
